import React, { Component } from 'react';
import { Container, Header, Content, Button, Text, H1, Icon, H3, Footer , ListItem, Fab, Spinner } from 'native-base';
import {View, Image, FlatList, TouchableNativeFeedback, Dimensions } from 'react-native';
import firebase from 'react-native-firebase';
import axios from 'axios';


const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height

export default class messageRecepients extends Component {

  /*
  static navigationOptions = ({ navigation }) => ({
    title: 'Chats',
    headerStyle: {
      backgroundColor: '#353666',
    },
    style: {
      backgroundColor: '#353666',
      height: 0.1 * SCREEN_HEIGHT
    },
    headerTintColor: '#fff'
  })
  */
  static navigationOptions = ({ navigation }) => ({
    header: null
  })

  constructor(props) {
    super(props);
    this.loadData = this.loadData.bind(this);
    this._renderList = this._renderList.bind(this);
    this.state = {
    active: false,
    random: false,
    isReady: false,
    recepients: [],
    username: null
    }
  } 

  loadData() {
    axios.get(`https://classcast-198812.appspot.com/teachersapp/chat_list/`)
    .then((res)=> {
      console.log("chat_list: "+JSON.stringify(res.data));
      this.setState({recepients: res.data.reverse(),
                        isReady: true
           })
    })
    .catch(err=> {console.log("errorrr: "+err)})

    axios.get(`https://classcast-198812.appspot.com/teachersapp/updateMessageSeenStatus`)
    
  }


_renderList({item, index}){
    console.log("data1234: "+JSON.stringify(item));
    return (
        <ListItem style={{flexDirection:'row', width: '90%', flex:21, backgroundColor: 'rgba(256,256,256,0.8)', marginBottom: 0.01 * SCREEN_HEIGHT, borderRadius: 0.02 * SCREEN_WIDTH}}
                  onPress={() => {
                    this.props.navigation.navigate('chatScreen', {
                      name: item.name,
                      username: item.username,
                      chat_id: item.chat_id
                    });
            }}>
            <View style={{flex: 5, alignItems: 'center', justifyContent: 'center'}}>
              <View style={{backgroundColor: '#f3e8f0', alignItems: 'center', justifyContent: 'center', borderRadius: 0.07 * SCREEN_WIDTH, height: 0.14 * SCREEN_WIDTH, width: 0.14 * SCREEN_WIDTH}}>
                <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.07 * SCREEN_WIDTH, color:'#f32a76'}}>{item.name[0]}</Text>
              </View>
            </View>
            <View style={{flex:11, justifyContent:'flex-start'}}>
                <Text style={{fontFamily: item.type == 'student' ? 'Montserrat-SemiBold': 'Montserrat-Bold', fontSize: 0.04 * SCREEN_WIDTH, alignSelf:'flex-start'}} >{item.name}</Text>
                <View style={{flexDirection:'row'}}>
                    <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.025 * SCREEN_WIDTH, color:'#f32a76'}}>{ item.type=="student"? item.batch_id: '' }</Text>
                    <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.025 * SCREEN_WIDTH, color:'#f32a76', marginLeft:5}}>Class {item.standard}</Text>
                </View>
            </View>
            <View style={{backgroundColor: '#f32a76', borderRadius: 0.02 * SCREEN_WIDTH, elevation: 4}}>
                <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.04 * SCREEN_WIDTH, color:'white', alignSelf: 'center', marginLeft: 0.02 * SCREEN_WIDTH, marginRight: 0.02 * SCREEN_WIDTH, marginTop: 0.003 * SCREEN_HEIGHT, marginBottom: 0.003 * SCREEN_HEIGHT}}>Click</Text>
              </View>
        </ListItem>


    );
}

  async componentDidMount(){

    var currentUser = await firebase.auth().currentUser;                 
     await currentUser.getIdToken()
            .then(idToken => {
                  console.log("sanusa: "+JSON.stringify(currentUser['email'].split('@')[0]))
                  //this.setState({ username: currentUser['email'].split('@')[0] });
                });


    const db = firebase.firestore()
        db.collection('chatLists')
          .doc(this.state.username)
            .onSnapshot((doc)=> {
              if (doc.exists) {
                this.loadData()
              }
            }),
            (error) => {
            console.error(error);
            };


    this._navListener = this.props.navigation.addListener('didFocus', () => {
      this.loadData()
    })

  }

  render() {
    return (
      <Container style={{ flex: 1, backgroundColor: '#e2e2e2'}}>
        <Text style={{fontFamily: 'Montserrat-Bold', fontSize: 0.06 * SCREEN_WIDTH, paddingBottom: 0.01 * SCREEN_HEIGHT, paddingTop: 0.05 * SCREEN_HEIGHT, color: 'black', textAlign: 'center'}}>Chats</Text> 
        <Image source={{uri: 'data:image/png;base64,'}}
                   style={{height: 0.6 * SCREEN_HEIGHT, width: '95%', position: 'absolute', marginTop: 0.3 * SCREEN_HEIGHT, opacity: 0.9, resizeMode: 'contain', alignSelf: 'center'}} />
        <Content style={{padding:2}}>
        { this.state.isReady &&
            <FlatList 
                data={this.state.recepients}
                extraData={this.state}
                renderItem={this._renderList}
                />  
         }
         { !this.state.isReady &&
          <Spinner color='red' />
         }    
        </Content>
        <View style={{ position: 'absolute', bottom: 0, right: 0}}>
          <Fab
            active={this.state.active}
            direction="up"
            containerStyle={{ }}
            style={{ backgroundColor: '#5067FF' }}
            position="bottomRight"
            onPress={() => {this.props.navigation.navigate('New Channel')}}>
            <Icon name="add" />
          </Fab>
        </View>            
      </Container>
    );
  }
}